css:
/* 墨迹：昼夜双版（:root 为日间基线，[data-reader-theme="night"] 覆盖夜景）；正文区占页高 80%+（蓝图硬约束①） */
:root{
  --ik-bg:#f7f3ea; --ik-fg:#242019; --ik-dim:#6f6656;
  --ik-ink:rgba(36,32,25,.16); --ik-seal:#a8322a; --ik-line:rgba(36,32,25,.20);
}
[data-reader-theme="night"]{
  --ik-bg:#141210; --ik-fg:#e9e2d4; --ik-dim:#9a9083;
  --ik-ink:rgba(233,226,212,.13); --ik-seal:#c8524a; --ik-line:rgba(233,226,212,.20);
}
html,body{margin:0;padding:0;background:var(--ik-bg);color:var(--ik-fg);
  font-family:"Noto Serif CJK SC","Source Han Serif SC",Georgia,serif;
  font-size:var(--md-font-size,18px);line-height:var(--md-line-height,1.95);}
body::before{content:"";position:absolute;left:-10%;right:-10%;bottom:0;height:13vh;pointer-events:none;opacity:.85;
  background:radial-gradient(60% 100% at 18% 100%,var(--ik-ink),transparent 70%),
    radial-gradient(50% 100% at 52% 100%,var(--ik-ink),transparent 72%),
    radial-gradient(64% 100% at 86% 100%,var(--ik-ink),transparent 70%);
  -webkit-mask-image:linear-gradient(180deg,transparent,#000 46%);mask-image:linear-gradient(180deg,transparent,#000 46%);}
body::after{content:"";position:absolute;left:-6%;top:-8%;width:46%;height:22%;pointer-events:none;
  background:radial-gradient(circle at 40% 40%,var(--ik-ink),transparent 68%);filter:blur(18px);}
.ik-head{position:relative;display:flex;justify-content:space-between;align-items:baseline;gap:.6em;
  padding:.85em 1.5em .5em;font-size:.76em;letter-spacing:.32em;color:var(--ik-dim);}
.ik-chapter{max-width:70%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.ik-pct{letter-spacing:.08em;font-variant-numeric:tabular-nums;}
.ik-title{position:relative;display:flex;align-items:center;gap:.8em;padding:1em 1.5em .55em;}
.ik-title-main{font-size:1.8em;font-weight:600;letter-spacing:.12em;}
.ik-title-main::after{content:"";display:block;width:2.6em;height:1px;margin-top:.5em;background:var(--ik-line);}
.ik-seal{display:inline-flex;align-items:center;justify-content:center;width:1.7em;height:1.7em;
  border-radius:4px;background:var(--ik-seal);color:#faf6ee;font-size:.8em;letter-spacing:0;}
.ik-body{position:relative;padding:.8em 1.5em 0;}
.ik-body .reader-chapter-title{margin:0 0 .8em;font-size:1.36em;font-weight:650;letter-spacing:.04em;}
.ik-body .reader-paragraph{margin:0 0 1em;text-indent:2em;}
.ik-body .reader-paragraph:first-of-type::first-letter{float:left;font-size:2.7em;line-height:.9;
  padding:.06em .14em 0 0;color:var(--ik-fg);}
.ik-body p{margin:0 0 1em;}
.ik-body a{color:inherit;text-decoration:underline;text-decoration-color:var(--ik-line);text-underline-offset:.2em;}
.ik-body blockquote{margin:0 0 1.05em;padding:.4em 0 .4em 1.05em;border-left:2px solid var(--ik-line);color:var(--ik-dim);}
.ik-body code{background:rgba(127,127,127,.14);padding:.12em .34em;border-radius:3px;font-family:"JetBrains Mono",Consolas,monospace;}
.ik-body pre{background:rgba(127,127,127,.10);padding:.8em;border-radius:3px;overflow-x:auto;}
.ik-body table{width:100%;border-collapse:collapse;}
.ik-body th,.ik-body td{border:1px solid var(--ik-line);padding:.35em .55em;}
.ik-foot{position:relative;display:flex;justify-content:space-between;align-items:center;gap:.8em;
  padding:.55em 1.5em .85em;font-size:.72em;color:var(--ik-dim);font-variant-numeric:tabular-nums;}
.ik-foot-mark{letter-spacing:.3em;opacity:.7;}
@media (prefers-reduced-motion:reduce){body::after{filter:blur(12px);}}
